/* Ahom Research Atlas: static, source-linked reading and browser-local notes. */
(() => {
 'use strict';
 const D=window.AHOM_DATA,C=window.AtlasCore,$=s=>document.querySelector(s),e=C.escapeHtml;
 const KEY='ahom-atlas-notebook-v1',LAST='ahom-atlas-last-page-v1';
 const anchorIds=D.manifest.anchors.map(a=>a.id);
 let notebook=C.emptyNotebook(),storageProblem=false,route='home',params=new URLSearchParams(),editing=null,pendingImport=null,toastTimer,lastDeleted=null;
 try {const raw=localStorage.getItem(KEY);if(raw)notebook=C.validateNotebook(JSON.parse(raw),anchorIds);}catch(err){storageProblem=true;}
 const source=id=>D.sources.find(s=>s.id===id);
 const sourceLink=id=>{const s=source(id);return s?`<a href="${e(s.url)}" target="_blank" rel="noopener">${e(s.short)} ↗</a>`:'';};
 const badge=(text,tone='')=>`<span class="badge ${tone}">${e(text)}</span>`;
 const lastPage=()=>{try{return C.pageNumber(localStorage.getItem(LAST));}catch{return 7;}};
 const currentPage=()=>C.pageNumber(params.get('page'),D.manifest.pages,lastPage());
 const activeAnchor=()=>D.manifest.anchors.find(a=>a.id===params.get('anchor')&&a.scanPage===currentPage());
 const contextId=()=>activeAnchor()?`anchor-${activeAnchor().id}`:`page-${currentPage()}`;
 function contextLabel(id){
   if(id.startsWith('page-'))return `Ahom-Buranji · scan page ${id.slice(5)}`;
   if(id.startsWith('anchor-')){const a=D.manifest.anchors.find(a=>a.id===id.slice(7));return a?`${a.label} · printed p. ${a.printedPage}`:'Source passage';}
   if(id.startsWith('lex-')){const row=D.lexicon.find(x=>x.id===id.slice(4));return row?`Bar Amra ${row.entry} · ${row.roman}`:'Lexicon note';}
   return 'Lengdon and the Nimi Jātaka';
 }
 function contextHref(id){
   if(id.startsWith('page-'))return `#reader?page=${id.slice(5)}`;
   if(id.startsWith('anchor-')){const a=D.manifest.anchors.find(a=>a.id===id.slice(7));return a?`#reader?page=${a.scanPage}&anchor=${a.id}`:'#reader';}
   return id.startsWith('lex-')?'#lexicon':'#research';
 }
 function saveNotebook(next){
   try{if(storageProblem){const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem(KEY+'-recovery-copy',raw);}localStorage.setItem(KEY,JSON.stringify(next));notebook=next;storageProblem=false;updateCount();return true;}
   catch{toast('Could not save in this browser. Existing notes have not been changed.');return false;}
 }
 function updateCount(){$('#note-count').textContent=notebook.notes.length;}
 function toast(message){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true;},3800);}
 function download(value,name,type='application/json'){
   const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}));
   const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);
 }
 function pageHead(eyebrow,title,description){return `<div class="page-head"><p class="eyebrow">${e(eyebrow)}</p><h1>${title}</h1><p>${description}</p></div>`;}
 function home(){
   return `<div class="wrap"><section class="hero"><div><p class="edition-label">Tai-Ahom texts · language · history</p><h1>Read the sources.<br><em>Trace the connections.</em></h1><p class="lede">A living research collection for exploring Ahom manuscripts, the words they preserve, and the histories they connect.</p><div class="actions"><a class="button" href="#reader?page=${lastPage()}">Enter the reading room <span aria-hidden="true">↗</span></a><a class="text-link" href="#research">Explore the research <span aria-hidden="true">→</span></a></div></div><div class="hero-art" aria-label="Original Ahom source pages"><img class="sheet" src="pages/010.webp" alt="Page 4 of the 1930 Ahom-Buranji edition" fetchpriority="high"><img class="sheet front" src="assets/passages/ab-p007-05.webp" alt="Ahom column of the shared-throne passage"><div class="hero-caption"><span>Ahom-Buranji · 1930</span><span>Original source images</span></div></div></section>
   <section class="stats" aria-label="Collection scope"><div class="stat"><strong>394</strong><span>source pages<br>ready to read</span></div><div class="stat"><strong>12</strong><span>passages with<br>source anchors</span></div><div class="stat"><strong>12</strong><span>lexical records<br>with provenance</span></div><div class="stat"><strong>01</strong><span>research<br>dossier</span></div></section>
   <div class="section-top"><div><p class="eyebrow">A PLACE TO BEGIN</p><h2>Inside the collection</h2></div><a href="#library">View collection →</a></div><section class="feature-grid"><article class="featured-volume"><div class="book-cover" aria-hidden="true"><small>TAI-AHOM<br>CHRONICLES</small><span>AHOM<br>BURANJI</span><small>1930</small></div><div class="volume-copy">${badge('Source edition')}<h3>Ahom-Buranji</h3><p>The complete supplied scan, with selected Ahom passages and a notebook for independent readings.</p><a class="text-link" href="#reader?page=7">Open the volume →</a></div></article><article class="dossier-feature"><p class="eyebrow">FEATURED INVESTIGATION</p><h3>Lengdon and the<br>Nimi Jātaka</h3><p>Follow the place-names, heavenly kings, and manuscript witnesses. Examine what each source can establish.</p><a class="text-link" href="#research">Read the evidence →</a></article></section>
   <section class="method-grid"><article class="method-card"><span class="num">01 / THE WITNESS</span><h3>Return to the page</h3><p>Keep the original scan beside every proposed reading. Scan pages and printed page numbers stay distinct.</p></article><article class="method-card"><span class="num">02 / THE READING</span><h3>Make uncertainty visible</h3><p>Inherited readings, provisional glosses and untranslated passages keep their individual status.</p></article><article class="method-card"><span class="num">03 / THE ARGUMENT</span><h3>Follow the evidence</h3><p>Separate observations, narrative comparisons and historical hypotheses, with references you can open.</p></article></section></div>`;
 }
 function catalogueCard(item){return `<article class="catalogue-card ${item.mode==='local'?'':'linked'}">${badge(item.status,item.mode==='reference'?'gray':'')}<h3>${e(item.title)}</h3><p>${e(item.subtitle)}</p><div class="meta-line"><span>${e(item.date)}</span><span>${e(item.type)}</span></div><p>${e(item.description)}</p><div class="actions"><a class="button small-btn ${item.mode==='local'?'':'secondary'}" href="${e(item.href)}" ${item.href.startsWith('http')?'target="_blank" rel="noopener"':''}>${e(item.action)} ${item.href.startsWith('http')?'↗':'→'}</a></div><div class="provenance">${e(item.extent)}<br>${sourceLink(item.source)}</div></article>`;}
 function library(){return `<div class="wrap">${pageHead('THE COLLECTION','Sources worth returning to.','Browse the available volume, linked working editions, and references for the next round of research.')}<div class="search-row"><div class="search-box"><input type="search" id="catalogue-search" aria-label="Search collection" placeholder="Search by title, source type, or subject…"></div><select id="catalogue-filter" aria-label="Filter collection"><option value="all">All sources</option><option value="local">Available in reader</option><option value="linked">Linked sources</option><option value="reference">Reference records</option></select></div><p class="results-caption" id="catalogue-count" aria-live="polite"></p><section id="catalogue-results" class="catalogue"></section><div class="notice" style="margin-top:28px"><strong>Edition and manuscript are different witnesses.</strong> The 1930 Buranji is a printed original-language edition. It is not a photograph of its underlying manuscript. Each additional witness needs its own catalogue record and page numbering.</div></div>`;}
 function updateCatalogue(){const q=$('#catalogue-search').value,filter=$('#catalogue-filter').value;const rows=D.catalogue.filter(x=>(filter==='all'||x.mode===filter)&&C.matches(q,[x.title,x.subtitle,x.type,x.description]));$('#catalogue-count').textContent=`${rows.length} source${rows.length===1?'':'s'}`;$('#catalogue-results').innerHTML=rows.map(catalogueCard).join('')||'<div class="empty">No sources match. Try a shorter title or another filter.</div>';}
 function reader(){
   const page=currentPage(),a=activeAnchor(),storedView=params.get('view');
   const view=['full','left','passage'].includes(storedView)?storedView:(a?'passage':page<7?'full':'left');
   const actualView=view==='passage'&&!a?'left':view;
   const book=notebook.bookmarks.some(b=>b.page===page),id=contextId(),note=notebook.notes.find(n=>n.id===id),printed=D.manifest.verifiedPrintedLabels[String(page)];
   const src=actualView==='passage'?a.image:`pages/${String(page).padStart(3,'0')}.webp`;
   try{localStorage.setItem(LAST,String(page));}catch{}
   return `<div class="reader-wrap"><div class="reader-top"><div><p class="eyebrow">THE READING ROOM</p><h1>Ahom-Buranji</h1><p>1930 printed edition · Original page order</p></div><div class="actions"><button class="button secondary small-btn" id="bookmark-page" aria-pressed="${book}">${book?'◆ Bookmarked':'◇ Bookmark page'}</button><button class="button secondary small-btn" id="copy-reference">Copy reference</button><button class="button small-btn" data-note="${id}">Add a note</button></div></div>
   <select class="reader-mobile-index" id="mobile-anchor" aria-label="Selected source passage"><option value="">Browse the complete volume</option>${D.manifest.anchors.map(x=>`<option value="${x.id}" ${a?.id===x.id?'selected':''}>p. ${x.printedPage} · ${e(x.label)}</option>`).join('')}</select>
   <div class="reader-layout"><aside class="reader-index"><p class="eyebrow">SELECTED PASSAGES</p><div class="anchor-list">${D.manifest.anchors.map(x=>`<a class="anchor-link ${a?.id===x.id?'active':''}" href="#reader?page=${x.scanPage}&anchor=${x.id}">${e(x.label)}<small>Printed p. ${x.printedPage} · scan ${x.scanPage}</small></a>`).join('')}</div><p class="small muted" style="padding:17px 11px">These are checked source locations. Independent transcriptions and translations remain pending.</p></aside>
   <section><div class="reader-panel"><div class="reader-toolbar"><div class="reader-pagination"><button class="icon-button" id="previous-page" aria-label="Previous scan page" ${page===1?'disabled':''}>‹</button><label for="page-number">Scan</label><input id="page-number" aria-label="Scan page number" type="number" min="1" max="394" value="${page}"><span>/ 394</span><button class="icon-button" id="next-page" aria-label="Next scan page" ${page===394?'disabled':''}>›</button></div><div class="segmented" aria-label="Source view">${a?`<button data-view="passage" class="${actualView==='passage'?'active':''}" aria-pressed="${actualView==='passage'}">Passage</button>`:''}<button data-view="left" class="${actualView==='left'?'active':''}" aria-pressed="${actualView==='left'}">Left column</button><button data-view="full" class="${actualView==='full'?'active':''}" aria-pressed="${actualView==='full'}">Full page</button></div><button class="icon-button" id="zoom-page" aria-label="Enlarge source image" aria-pressed="false">＋</button></div><div class="reader-surface" tabindex="0" aria-label="Scrollable source image"><div class="scan-frame ${actualView==='left'?'ahom-only':actualView}" id="scan-frame"><img id="scan-image" src="${src}" alt="${a&&actualView==='passage'?e(a.label)+' in the Ahom column':`Ahom-Buranji scan page ${page}, ${actualView==='left'?'left column':'complete page'}`}" decoding="async"></div><div class="image-error" id="image-error" hidden><h3>Page could not load.</h3><p>Reconnect to load a page you have not opened before.</p><button class="button secondary" id="retry-image">Retry page</button></div></div><div class="reader-caption"><span>Scan ${page}${printed?` · printed p. ${printed}`:''}</span><span>${actualView==='passage'?'Ahom passage crop':actualView==='left'?'Left-column viewing mask':'Complete printed page'}</span></div></div><p class="reader-page-caption">${a?e(a.label)+' · ':''}Source images are preserved. Full-page view includes the edition’s historical English column.</p></section>
   <aside class="reading-sidebar"><section class="reading-card"><p class="eyebrow">READING STATUS</p><h3>${a?'Independent reading':'Source page'}</h3>${badge('Transcription pending','amber')}<div class="field-status" style="margin-top:17px"><strong>Unicode transcription</strong><span>No independently certified text yet.</span></div><div class="field-status"><strong>Fresh English translation</strong><span>Awaiting an accepted Ahom reading.</span></div><p class="small">The printed English is not used to fill these fields. Add a proposed reading to your notebook for later review.</p></section><section class="reading-card"><p class="eyebrow">MY NOTEBOOK</p><h3>${note?'Your reading note':'Keep a reading note'}</h3><p class="note-preview">${note?e(note.text):'Record a word, an alternative reading, or a question for this source location.'}</p><button class="button secondary small-btn" data-note="${id}">${note?'Edit note':'Write a note'}</button><p class="small" style="margin:12px 0 0">Stored on this device.</p></section><section class="reading-card"><p class="eyebrow">SOURCE RECORD</p><p>Golap Chandra Barua, ed., <em>Ahom-Buranji</em>, 1930. Scan page ${page}${printed?`, printed p. ${printed}`:''}.</p><div class="small">${sourceLink('buranji')}</div><a class="text-link" href="#about" style="margin-top:12px">Editorial method →</a></section></aside></div></div>`;
 }
 function changePage(value){const p=C.pageNumber(value,D.manifest.pages,0);if(!p){toast('Choose a scan page between 1 and 394.');$('#page-number').value=currentPage();return;}location.hash=`reader?page=${p}&view=${params.get('view')==='full'?'full':'left'}`;}
 function lexiconCard(row){return `<article class="lexicon-item"><div class="lex-top"><span class="ahom" lang="aho">${e(row.script)}</span><span class="roman">${e(row.roman)}</span></div><p class="gloss">${e(row.gloss)}</p>${badge(row.confidence==='C'?'Meaning unresolved':'Inherited reading',row.confidence==='C'?'amber':'gray')}<details style="margin-top:18px"><summary>Assamese explanation &amp; provenance</summary><p class="eyebrow" style="font-size:9px">ASSAMESE WRITTEN IN AHOM SCRIPT</p><p class="ahom" lang="as-Ahom">${e(row.explanation)}</p><p>${e(row.explanationRoman)}</p><p>Defining formula: <span lang="aho" style="font-family:Ahom;font-size:20px">${e(row.formula)}</span></p><p>Folio ${e(row.folio)}, entry ${e(row.entry)}. Confidence ${e(row.confidence)} in the working edition. ${e(row.headwordCheck)}. The complete entry has not been independently certified here.</p><button class="button secondary small-btn" data-note="lex-${row.id}" style="margin-top:12px">Note this entry</button></details><p class="source-line"><span>BAR AMRA · ${e(row.entry)}</span><a href="${e(source('bar-amra-working').url)}" target="_blank" rel="noopener">Source edition ↗</a></p></article>`;}
 function lexicon(){return `<div class="wrap">${pageHead('WORDS IN CONTEXT','A lexicon with a memory.','Explore a small, attributed selection from the Bar Amra working edition. Identical spellings can have several glosses; the source context stays attached.')}<div class="search-row"><div class="search-box"><input type="search" id="lexicon-search" aria-label="Search lexicon" placeholder="Search Ahom text, transliteration, meaning, or folio…"></div><select id="lexicon-filter" aria-label="Filter lexical records"><option value="all">All readings</option><option value="gloss">With a recorded gloss</option><option value="unresolved">Unresolved meaning</option></select></div><p class="results-caption" id="lexicon-count" aria-live="polite"></p><div class="lexicon-layout"><section id="lexicon-results" class="lexicon-list"></section><aside class="lexicon-aside"><div class="reading-card">${badge('12 sample records')}<h3>Script is not language.</h3><p>The headword is Tai-Ahom. The explanation is Assamese written in Ahom script. They remain separate fields.</p><p>These inherited readings come from the 14 October 2026 project edition, based on scholarly manuscript sources.</p><div class="small">${sourceLink('dictionary-project')}</div></div><div class="notice"><strong>Coverage remains incomplete.</strong><p>The 14 October snapshot has 1,230 recovered records, but four folios are untranscribed and other entry numbers are missing. Confidence labels describe the source edition; encoding validity alone does not verify a reading.</p></div></aside></div></div>`;}
 function updateLexicon(){const q=$('#lexicon-search').value,filter=$('#lexicon-filter').value;const rows=D.lexicon.filter(x=>(filter==='all'||(filter==='unresolved'?x.confidence==='C':x.confidence!=='C'))&&C.matches(q,[x.script,x.roman,x.gloss,x.folio,x.entry,x.explanation,x.explanationRoman]));$('#lexicon-count').textContent=`${rows.length} of ${D.lexicon.length} sample records · Romanization and Ahom-script search`;$('#lexicon-results').innerHTML=rows.map(lexiconCard).join('')||'<div class="empty">No entries match. Try an English gloss such as “fowl”, a transliteration such as “kai”, or a folio such as “1v”.</div>';}
 function evidenceCard(c){return `<article class="evidence-card">${badge(c.label,c.category==='hypothesis'?'amber':c.category==='comparison'?'gray':'')}<h3>${e(c.title)}</h3><p>${e(c.text)}</p><div class="source-locator"><strong>${e(c.locator)}</strong><p style="margin:10px 0 0">${c.sources.map(sourceLink).join(' · ')}</p>${c.anchor?`<a class="text-link" href="#reader?page=${D.manifest.anchors.find(a=>a.id===c.anchor).scanPage}&anchor=${c.anchor}" style="margin-top:10px">Inspect the Ahom passage →</a>`:''}<p class="review-note">${e(c.review)}</p></div></article>`;}
 function research(){return `<div class="wrap">${pageHead('RESEARCH DOSSIER 01','Lengdon and the Nimi Jātaka','A source-led investigation into heavenly kings, Mithilā, and the possible adaptation of Buddhist royal narratives in Ahom tradition.')}<div class="research-intro"><section class="assessment"><p class="eyebrow">CURRENT ASSESSMENT</p><h3>A meaningful comparison.<br>An open historical question.</h3><p>The material supports investigating Buddhist narrative connections. The exact source, transmission route, and scope of adaptation still require manuscript-level comparison.</p></section><section class="explanation"><h3>Keep three levels distinct.</h3><p><strong>Observation:</strong> a passage or record that can be located.<br><strong>Comparison:</strong> a feature shared with another text.<br><strong>Hypothesis:</strong> an explanation of how the relationship arose.</p><p>This dossier carries forward the project’s 10 October 2026 audit. Source locations and selected online references were rechecked for this release; inherited findings are labelled.</p><div class="actions"><button class="button secondary small-btn" data-note="research-lengdon-nimi">Add a research note</button><button class="button secondary small-btn" id="print-research">Print dossier</button></div></section></div><div class="section-top"><h2>Follow the evidence</h2><a href="#about">All sources →</a></div><div class="evidence-filters" aria-label="Filter evidence"><button class="filter-button active" data-evidence="all" aria-pressed="true">All evidence</button><button class="filter-button" data-evidence="observation" aria-pressed="false">Source observations</button><button class="filter-button" data-evidence="comparison" aria-pressed="false">Comparisons</button><button class="filter-button" data-evidence="hypothesis" aria-pressed="false">Open hypotheses</button></div><section class="evidence-grid" id="evidence-results">${D.claims.map(evidenceCard).join('')}</section><section class="research-next"><h3>What would move the argument forward?</h3><ol><li>Collate the Bithila, Mungthila and shared-throne passages against distinct manuscript witnesses.</li><li>Compare the Ahom Nemi witness with Nimi and Sādhina, tracking wording and narrative sequence.</li><li>Trace the Shan–Yunnan references cited by Gogoi without equating a reused place-name with a proven migration.</li><li>Test royal Buddhist practice ruler by ruler using dated inscriptions, dedications or explicit court records.</li></ol></section></div>`;}
 function notebookView(){const sorted=[...notebook.notes].sort((a,b)=>Date.parse(b.updated)-Date.parse(a.updated));return `<div class="wrap">${pageHead('YOUR READING DESK','A notebook of your own.','Keep observations close to the source. Your notes stay in this browser; exported backups let you carry them to another device.')}${lastDeleted?`<div class="notice" style="margin-bottom:20px">Note removed. <button class="button secondary small-btn" id="undo-delete">Undo</button></div>`:''}<div class="notebook-grid"><section><div class="notebook-tabs"><h3>Reading notes <span class="muted">(${notebook.notes.length})</span></h3></div>${sorted.length?sorted.map(n=>`<article class="note-card"><span class="note-meta">${new Date(n.updated).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}</span><h3><a href="${contextHref(n.id)}">${e(contextLabel(n.id))}</a></h3><p>${e(n.text)}</p><div class="actions"><button class="button secondary small-btn" data-note="${e(n.id)}">Edit note</button><button class="danger-link" data-delete-note="${e(n.id)}">Delete note</button></div></article>`).join(''):'<div class="empty"><h3>Begin with a passage.</h3><p>Add a note from the reader, a dictionary entry, or the research dossier.</p><a class="button secondary" href="#reader">Open the reading room →</a></div>'}</section><aside><div class="reading-card"><p class="eyebrow">KEEP A COPY</p><h3>Back up your notebook</h3><p>Browser data can be cleared. Export a dated JSON backup after a reading session.</p><div class="actions"><button class="button" id="export-notebook">Export notebook ↓</button><button class="button secondary" id="import-notebook">Import backup</button></div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="small" style="margin:13px 0 0">Import merges notes; it does not replace the published source text.</p></div><div style="margin-top:27px"><h3>Bookmarked pages <span class="muted">(${notebook.bookmarks.length})</span></h3>${notebook.bookmarks.length?[...notebook.bookmarks].sort((a,b)=>a.page-b.page).map(b=>`<div class="bookmark"><a href="#reader?page=${b.page}">Ahom-Buranji · scan ${b.page} →</a><button class="icon-button" data-remove-bookmark="${b.page}" aria-label="Remove bookmark for scan page ${b.page}">×</button></div>`).join(''):'<p class="small muted">Use “Bookmark page” in the reader to save a location.</p>'}</div></aside></div></div>`;}
 function about(){return `<div class="wrap">${pageHead('EDITORIAL METHOD','A clear trail back to the source.','This first release makes source material usable while keeping the limits of the transcription and historical research visible.')}<div class="about-grid"><section><h2>What is in this release?</h2><p>All 394 pages of the supplied <em>Ahom-Buranji</em> scan are available as reading images. Twelve selected Ahom passages have high-resolution crops and checked source locations. Twelve Bar Amra sample entries preserve inherited Unicode readings and provenance. One dossier separates observations, comparisons and hypotheses.</p><h2>What does “checked” mean?</h2><p>A checked source anchor means the crop and page location have been inspected. It does not certify the reading of every character. No complete Buranji passage has been independently certified in Unicode or freshly translated for this release. Pending fields are deliberately left unfilled.</p><p>Bar Amra readings are inherited from the provisional working edition. Its confidence codes and separation of Tai-Ahom from Assamese in Ahom script are retained. The selected headword check reported for entry 1v-4 does not certify its entire entry.</p><h2>How to contribute</h2><p>Record an observation with a source location and an image reference. Supply your proposed transcription, translation, reasoning, and any alternative reading. Keep the original source intact. Changes to shared data should be reviewed before their status is raised.</p><h2>Your notebook</h2><p>Notes and bookmarks use browser-local storage. They are not sent to a server and do not change the published edition. Import and export let you move your notes yourself. This site contains no analytics script or external AI service.</p><h2>Source images and typography</h2><p>Reading images are resized WebP derivatives; the original archived scan remains linked for close examination. Passage crops are rendered separately at higher resolution. Source page order is preserved and printed labels are asserted only where checked.</p><p>The Ahom font is Noto Serif Ahom by the Noto Project Authors, distributed under the <a href="assets/OFL-Ahom.txt">SIL Open Font License</a>. The app’s code license does not relicense third-party editions or linked resources.</p></section><aside><section class="reading-card"><p class="eyebrow">RELEASE 0.1.0 · 23 OCTOBER 2026</p><h3>Coverage, precisely</h3><dl class="stat-list"><dt>Source pages</dt><dd>394 / 394</dd><dt>Checked source anchors</dt><dd>12</dd><dt>Certified Buranji translations</dt><dd>0</dd><dt>Lexical samples</dt><dd>12</dd><dt>Research dossiers</dt><dd>1</dd></dl><p class="small">A complete scan is not a complete transcription or translation.</p></section><section class="reading-card" style="margin-top:20px"><p class="eyebrow">REUSABLE RESEARCH DATA</p><h3>Take the data with you</h3><div class="download-grid"><a class="download-link" href="data/source-manifest.json" download>Source manifest <span>↓ JSON</span></a><a class="download-link" href="data/lexicon.json" download>Lexicon samples <span>↓ JSON</span></a><a class="download-link" href="data/research.json" download>Research dossier <span>↓ JSON</span></a><a class="download-link" href="data/catalogue.json" download>Catalogue <span>↓ JSON</span></a></div></section><section class="reading-card" style="margin-top:20px"><p class="eyebrow">SOURCE FINGERPRINT</p><p>SHA-256 of the supplied PDF:</p><p class="mono">${D.manifest.sha256}</p><p class="small">Use this to distinguish the source file from a later scan or edition.</p></section></aside></div><div class="section-top"><h2>References &amp; verification record</h2></div><section class="bibliography">${D.sources.map((s,i)=>`<article class="source-entry"><span class="source-num">${String(i+1).padStart(2,'0')}</span><div><a href="${e(s.url)}" target="_blank" rel="noopener">${e(s.title)} ↗</a><div>${e(s.author)} · ${e(s.date)}</div><p>${e(s.type)}. ${e(s.review)}</p></div></article>`).join('')}</section></div>`;}
 function bindView(){
   if(route==='library'){updateCatalogue();$('#catalogue-search').addEventListener('input',updateCatalogue);$('#catalogue-filter').addEventListener('change',updateCatalogue);}
   if(route==='lexicon'){updateLexicon();$('#lexicon-search').addEventListener('input',updateLexicon);$('#lexicon-filter').addEventListener('change',updateLexicon);}
   if(route==='research'){$('#print-research').onclick=()=>{document.querySelector('[data-evidence="all"]').click();window.print();};document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-evidence]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#evidence-results').innerHTML=D.claims.filter(c=>b.dataset.evidence==='all'||c.category===b.dataset.evidence).map(evidenceCard).join('');});}
   if(route==='reader'){
     if(activeAnchor() && (!params.has('view')||params.get('view')==='passage'))$('.reader-surface').classList.add('passage-view');
     $('#previous-page').onclick=()=>changePage(currentPage()-1);$('#next-page').onclick=()=>changePage(currentPage()+1);
     $('#page-number').onchange=event=>changePage(event.target.value);$('#page-number').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();changePage(event.target.value);}};
     $('#mobile-anchor').onchange=event=>{const a=D.manifest.anchors.find(a=>a.id===event.target.value);location.hash=a?`reader?page=${a.scanPage}&anchor=${a.id}`:`reader?page=${currentPage()}`;};
     document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{const p=new URLSearchParams(params);p.set('page',currentPage());p.set('view',b.dataset.view);location.hash=`reader?${p}`;});
     $('#zoom-page').onclick=()=>{const z=$('#scan-frame').classList.toggle('zoomed');$('#zoom-page').setAttribute('aria-pressed',String(z));$('#zoom-page').textContent=z?'−':'＋';$('#zoom-page').setAttribute('aria-label',z?'Fit source image':'Enlarge source image');};
     $('#bookmark-page').onclick=()=>{const p=currentPage(),exists=notebook.bookmarks.some(b=>b.page===p);const next={...notebook,bookmarks:exists?notebook.bookmarks.filter(b=>b.page!==p):[...notebook.bookmarks,{id:`page-${p}`,page:p}]};if(saveNotebook(next)){render(false);toast(exists?'Bookmark removed.':'Page bookmarked.');}};
     $('#copy-reference').onclick=async()=>{const a=activeAnchor();const permalink=new URL(location.href);permalink.hash=`reader?page=${currentPage()}${a?'&anchor='+a.id:''}`;const ref=`Golap Chandra Barua (ed.), Ahom-Buranji (1930), ${a?`printed p. ${a.printedPage}, ${a.label}, `:''}scan page ${currentPage()} of 394. ${permalink.href}`;try{await navigator.clipboard.writeText(ref);toast('Source reference copied.');}catch{download(ref,'Ahom_Buranji_Reference.txt','text/plain');toast('Reference downloaded.');}};
     const img=$('#scan-image'),showError=()=>{$('#image-error').hidden=false;$('#scan-frame').hidden=true;};img.onerror=showError;if(img.complete&&!img.naturalWidth)showError();
     $('#retry-image').onclick=()=>{$('#image-error').hidden=true;$('#scan-frame').hidden=false;img.src=img.getAttribute('src');};
   }
   if(route==='notebook'){
     document.querySelectorAll('[data-delete-note]').forEach(b=>b.onclick=()=>{const removed=notebook.notes.find(n=>n.id===b.dataset.deleteNote);if(saveNotebook({...notebook,notes:notebook.notes.filter(n=>n.id!==b.dataset.deleteNote)})){lastDeleted=removed;render(false);toast('Note removed. Undo is available above your notes.');}});
     if($('#undo-delete'))$('#undo-delete').onclick=()=>{if(lastDeleted&&saveNotebook({...notebook,notes:[...notebook.notes,lastDeleted]})){lastDeleted=null;render(false);toast('Note restored.');}};
     $('#export-notebook').onclick=()=>{download({...notebook,exportedAt:new Date().toISOString()},`Ahom_Atlas_Notebook_${new Date().toISOString().slice(0,10)}.json`);toast('Notebook export prepared.');};
     $('#import-notebook').onclick=()=>$('#import-file').click();
     $('#import-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Please choose a notebook smaller than 2 MB.');pendingImport=C.validateNotebook(JSON.parse(await file.text()),anchorIds);$('#import-summary').textContent=`This backup contains ${pendingImport.notes.length} notes and ${pendingImport.bookmarks.length} bookmarks.`;$('#import-dialog').showModal();}catch(err){toast(err instanceof SyntaxError?'This is not valid JSON. Nothing was changed.':err.message);}event.target.value='';};
     document.querySelectorAll('[data-remove-bookmark]').forEach(b=>b.onclick=()=>{if(saveNotebook({...notebook,bookmarks:notebook.bookmarks.filter(x=>x.page!==Number(b.dataset.removeBookmark))})){render(false);toast('Bookmark removed.');}});
   }
 }
 function render(scroll=true){
   const raw=location.hash.slice(1)||'home';const [key,query='']=raw.split('?');route=['home','library','reader','lexicon','research','notebook','about'].includes(key)?key:'home';params=new URLSearchParams(query);
   const views={home,library,reader,lexicon,research,notebook:notebookView,about};
   $('#main').innerHTML=(storageProblem?'<div class="wrap" style="padding-top:20px"><p class="error-banner">Your saved notebook could not be read. Export any existing backup before making changes, or use another browser.</p></div>':'')+views[route]();
   document.querySelectorAll('[data-nav]').forEach(a=>{const on=a.dataset.nav===route;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
   document.title=`${{home:'Ahom Research Atlas',library:'Collection',reader:'Ahom-Buranji reader',lexicon:'Bar Amra lexicon',research:'Lengdon and Nimi',notebook:'My notebook',about:'Sources and method'}[route]}${route==='home'?'':' · Ahom Research Atlas'}`;
   bindView();updateCount();if(scroll)window.scrollTo({top:0,behavior:'instant'});
 }
 $('#main').addEventListener('click',event=>{const b=event.target.closest('[data-note]');if(!b)return;editing=b.dataset.note;$('#note-context').textContent=contextLabel(editing);$('#note-text').value=notebook.notes.find(n=>n.id===editing)?.text||'';$('#note-dialog').showModal();$('#note-text').focus();});
 const closeNote=()=>{$('#note-dialog').close();editing=null;};$('#close-note').onclick=closeNote;$('#cancel-note').onclick=closeNote;
 $('#note-form').onsubmit=event=>{event.preventDefault();const text=$('#note-text').value.trim();if(!text){toast('Write a note before saving.');return;}const n={id:editing,text,updated:new Date().toISOString()};if(saveNotebook({...notebook,notes:[...notebook.notes.filter(x=>x.id!==editing),n]})){closeNote();render(false);toast('Note saved on this device.');}};
 const closeImport=()=>{$('#import-dialog').close();pendingImport=null;};$('#close-import').onclick=closeImport;$('#cancel-import').onclick=closeImport;
 $('#confirm-import').onclick=()=>{if(!pendingImport)return;const next=C.mergeNotebooks(notebook,pendingImport);if(saveNotebook(next)){closeImport();render(false);toast('Notebook merged.');}};
 document.addEventListener('keydown',event=>{if(route!=='reader'||event.altKey||event.ctrlKey||event.metaKey||/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName)||$('#note-dialog').open||$('#import-dialog').open)return;if(event.key==='ArrowRight'&&currentPage()<394){event.preventDefault();changePage(currentPage()+1);}if(event.key==='ArrowLeft'&&currentPage()>1){event.preventDefault();changePage(currentPage()-1);}});
 $('.skip').onclick=event=>{event.preventDefault();$('#main').focus();};
 window.addEventListener('hashchange',()=>render());render();
 if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});
})();
